package com.booksyde.dto.request; import jakarta.validation.constraints.*; public record CreateBookRequest(@NotBlank @Size(max=180) String title,@Size(max=180) String author,@Size(max=120) String category,@Size(max=3000) String description,@Size(max=10000) String synopsis,@NotBlank @Pattern(regexp="manga|hq|gibi|book") String workType,@NotBlank @Size(max=220) String slug,@Pattern(regexp="private|public|unlisted") String visibility,boolean collection,@Size(max=2000) String coverUrl,@Min(0) int priceCents,@Size(max=40) String distributionChannel){}